sp_widget.css:
.pre-line {
  white-space: pre-line;
}
.side-info {
  background: #fcfcfc;
  padding: 15px;
  border-radius: 4px;
  border: 1px solid #eee;
}
.info-group {
  margin-bottom: 15px;
}
.info-group label {
  color: #777;
  font-size: 11px;
  text-transform: uppercase;
  display: block;
  margin-bottom: 2px;
}
.info-group div {
  font-weight: 500;
  color: #333;
}

sp_widget.script:
(function() {
  var sys_id = $sp.getParameter('sys_id') || options.sys_id;
  if (!sys_id) return;
  var gr = new GlideRecordSecure('x_1603911_casepo_0_legal_case');
  if (gr.get(sys_id)) {
    data.case = {
      sys_id: gr.getUniqueValue(),
      number: gr.getValue('number'),
      short_description: gr.getValue('short_description'),
      description: gr.getValue('description'),
      state: gr.getDisplayValue('state'),
      priority: gr.getDisplayValue('ai_priority'), // Using AI Priority
      ai_category: gr.getDisplayValue('ai_category'),
      requestor: gr.getDisplayValue('legal_requestor'),
      created: gr.getDisplayValue('sys_created_on')
    };
    // Fetch Case Documents
    data.documents = [];
    var docGR = new GlideRecordSecure('x_1603911_casepo_0_case_document');
    docGR.addQuery('parent_case', sys_id);
    docGR.orderByDesc('uploaded_on');
    docGR.query();
    while (docGR.next()) {
      data.documents.push({
        sys_id: docGR.getUniqueValue(),
        version: docGR.getValue('document_version'),
        is_latest: docGR.getValue('is_latest_version') == '1',
        uploaded_on: docGR.getDisplayValue('uploaded_on'),
        uploaded_by: docGR.getDisplayValue('uploaded_by')
      });
    }
  }
})();
